#![allow(clippy::excessive_precision)]

use thermopack_rs::component::component;
use thermopack_rs::solid_saturation::{
    SolidSaturationSpecification, solid_co2_saturation, solid_co2_with_fluid_reference,
};
use thermopack_rs::{Cubic, CubicKind, IdealGas, Phase};

const PRESSURE_RTOL: f64 = 1e-6;
const TEMPERATURE_ATOL: f64 = 1e-8;
const TEMPERATURE_RTOL: f64 = 1e-9;

#[test]
fn solid_saturation_matches_the_source() {
    let model = Cubic::new(CubicKind::PengRobinson, &["CO2"]).unwrap();
    let solid = solid_co2_with_fluid_reference(&model).unwrap();
    let ideal = IdealGas::new(component("CO2").unwrap()).unwrap();
    let mut checked = 0;
    for row in include_str!("fixtures/solid_saturation.csv")
        .lines()
        .skip(1)
    {
        let fields: Vec<_> = row.split(';').collect();
        let case = fields[0];
        let specified: f64 = fields[2].parse().unwrap();
        let guess: f64 = fields[3].parse().unwrap();
        let source_t: f64 = fields[4].parse().unwrap();
        let source_p: f64 = fields[5].parse().unwrap();
        let (specification, initial) = match fields[1] {
            "T" => (
                SolidSaturationSpecification::FixedTemperature(specified),
                (specified, guess),
            ),
            _ => (
                SolidSaturationSpecification::FixedPressure(specified),
                (guess, specified),
            ),
        };
        let solution = solid_co2_saturation(
            &model,
            &solid,
            &ideal,
            specification,
            initial,
            Phase::Liquid,
        )
        .unwrap();
        assert!(
            solution.residual.abs() < 1e-9,
            "{case}: residual {}",
            solution.residual
        );
        if fields[1] == "T" {
            let difference = (source_p - solution.pressure).abs();
            assert!(
                difference <= PRESSURE_RTOL * source_p.abs(),
                "{case}: source {source_p} native {}",
                solution.pressure
            );
            assert!((source_t - solution.temperature).abs() < 1e-9, "{case}");
        } else {
            let difference = (source_t - solution.temperature).abs();
            assert!(
                difference <= TEMPERATURE_ATOL + TEMPERATURE_RTOL * source_t.abs(),
                "{case}: source {source_t} native {}",
                solution.temperature
            );
            assert!((source_p - solution.pressure).abs() < 1e-6, "{case}");
        }
        checked += 1;
    }
    assert_eq!(checked, 6);
}

#[test]
fn the_solid_reference_follows_the_fluid() {
    // The reference levels of the solid model are the entropy and the Gibbs
    // energy of the liquid at the triple point, so the solid starts on the
    // fluid at the triple point of the original.
    let model = Cubic::new(CubicKind::PengRobinson, &["CO2"]).unwrap();
    let solid = solid_co2_with_fluid_reference(&model).unwrap();
    let saturation = model.saturation_pressure(216.592).unwrap();
    let state = model.prepare(216.592, &[1.0]).unwrap();
    let entropy = state.entropy(saturation.liquid_volume).unwrap();
    let enthalpy = state.enthalpy(saturation.liquid_volume).unwrap();
    let gibbs = enthalpy - 216.592 * entropy;
    let solid_gibbs = solid.gibbs(216.592, saturation.pressure);
    let solid_entropy = solid.entropy(216.592, saturation.pressure);
    // The reference levels place the solid on the liquid at the triple point:
    // the Gibbs energies agree and the solid carries the lower entropy of the
    // melting line.
    assert!((gibbs - solid_gibbs).abs() < 1e-6 * gibbs.abs());
    assert!(solid_entropy < entropy);
    assert!((entropy - solid_entropy) * 216.592 > 1e3);
}

#[test]
fn the_saturation_solves_both_specifications() {
    // The temperature of the line and the pressure of the line must be
    // consistent with each other.
    let model = Cubic::new(CubicKind::PengRobinson, &["CO2"]).unwrap();
    let solid = solid_co2_with_fluid_reference(&model).unwrap();
    let ideal = IdealGas::new(component("CO2").unwrap()).unwrap();
    let from_temperature = solid_co2_saturation(
        &model,
        &solid,
        &ideal,
        SolidSaturationSpecification::FixedTemperature(216.600),
        (216.600, 550000.0),
        Phase::Liquid,
    )
    .unwrap();
    let from_pressure = solid_co2_saturation(
        &model,
        &solid,
        &ideal,
        SolidSaturationSpecification::FixedPressure(from_temperature.pressure),
        (216.600, from_temperature.pressure),
        Phase::Liquid,
    )
    .unwrap();
    assert!((from_temperature.temperature - from_pressure.temperature).abs() < 1e-8);
    assert!((from_temperature.pressure - from_pressure.pressure).abs() < 1e-6);
}
